DROP TABLE IF EXISTS `wptests_mpprecipe_recipes`;
CREATE TABLE `wptests_mpprecipe_recipes` (
  `recipe_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_id` bigint(20) unsigned NOT NULL,
  `recipe_title` text,
  `recipe_image` text,
  `summary` text,
  `rating` text,
  `prep_time` text,
  `cook_time` text,
  `total_time` text,
  `yield` text,
  `serving_size` varchar(50) DEFAULT NULL,
  `calories` varchar(50) DEFAULT NULL,
  `fat` varchar(50) DEFAULT NULL,
  `ingredients` text,
  `instructions` text,
  `notes` text,
  `author` text,
  `original` text,
  `original_excerpt` text,
  `original_type` text,
  `cuisine` text,
  `type` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `carbs` varchar(50) DEFAULT NULL,
  `protein` varchar(50) DEFAULT NULL,
  `fiber` varchar(50) DEFAULT NULL,
  `transfat` varchar(50) DEFAULT NULL,
  `unsatfat` varchar(50) DEFAULT NULL,
  `satfat` varchar(50) DEFAULT NULL,
  `sodium` varchar(50) DEFAULT NULL,
  `sugar` varchar(50) DEFAULT NULL,
  `cholesterol` varchar(50) DEFAULT NULL,
  `nutrition_tags` text,
  `server_recipe_id` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`recipe_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
LOCK TABLES `wptests_mpprecipe_recipes` WRITE;
INSERT INTO `wptests_mpprecipe_recipes` (`recipe_id`, `post_id`, `recipe_title`, `recipe_image`, `summary`, `rating`, `prep_time`, `cook_time`, `total_time`, `yield`, `serving_size`, `calories`, `fat`, `ingredients`, `instructions`, `notes`, `author`, `original`, `original_excerpt`, `original_type`, `cuisine`, `type`, `created_at`, `carbs`, `protein`, `fiber`, `transfat`, `unsatfat`, `satfat`, `sodium`, `sugar`, `cholesterol`, `nutrition_tags`, `server_recipe_id`)
VALUES
	(1,33466,'Vegan Cinnamon Roll\'s','http://pinchofyum.com/wp-content/uploads/Miracle-No-Knead-Bread-3-2-Square.jpg','These easy vegan cinnamon rolls are just like the real thing, but with no dairy and no eggs! Fluffy, sweet, and a bit chewy, these are everything you’ve ever dreamed of in a cinnamon roll.',NULL,'PT2H','PT30M','PT2H30M','10 rolls','1 roll','729','0','!for the [i]dough[/i]:\r\n\r\n15 1/2 oz [i]all-purpose[/i] flour\r\n3 Tbsp granulated sugar\r\n1 1/4 tsp salt\r\n1 1/2 tsp active dry yeast\r\n8 oz non-dairy milk, lukewarm*\r\n6 Tbsp (3 oz) vegan butter, melted\r\n!for the filling:\r\n\r\n1/4 cup granulated sugar1\r\n1/2 tsp ground cinnamon\r\n2 tsp all-purpose flour\r\n2 tsp non-dairy milk\r\n!for the frosting:\r\n\r\n1 1/4 cups powdered sugar\r\n1/2 tsp vanilla extract\r\n2-3 Tbsp non-dairy milk','!make the dough:\r\nCombine the flour, sugar, and [salt|https://example.com] in a [large bowl|https://example.com rel=\'nofollow\'] (use the bowl of your stand mixer if you have one) and mix to combine. Mix in the yeast. Add the lukewarm nondairy milk and the melted butter and mix to create a shaggy dough using a danish dough whisk or a large wooden spoon.\r\nIf you have a stand mixer, mix using the dough hook on low speed for 7-8 minutes, until smooth. If you are kneading by hand, dump the dough onto a lightly floured solid surface and knead for 10-12 minutes, until smooth. The dough should be tacky but not terribly sticky.\r\nOil your hands with spray oil, then remove the dough from the bowl and form into a ball by stretching the dough from the sides around to the bottom. Spray the bowl with the oil, then place the dough seam-side down in the bowl. Spray the top of the dough with the oil, then cover the bowl with plastic wrap.\r\nLet rise in a warm place* for 60-90 minutes, until doubled in size.\r\n!form the rolls:\r\nCombine the granulated sugar, cinnamon, and flour for the filling in a small bowl. Grease a 8×12″ baking dish with spray oil.\r\nWhen the dough is done rising, use some spray oil to grease a solid work surface and dump the dough out of the bowl. Use a rolling pin to roll into a 12×15″ rectangle.\r\nUse a silicone pastry brush to spread a thin layer of almond milk on top of the dough, then sprinkle the filling all across, leaving a 1/2″ at one side to help the edges seal.\r\nRoll the dough from the short edge into a tube. When you reach the edge that wasn’t covered by the filling, pinch the seam to seal.\r\nTake a long piece of dental floss and bring it under the tube of dough. Cross the floss across the top, then pull tight to cut the roll. Cut the roll into 10 even pieces and arrange in the baking dish with about 1 inch between rolls.\r\nCover the dish with plastic wrap and refrigerate overnight.\r\nThe next morning, remove the rolls from the fridge (they should have gotten a bit puffy) and let sit for 30 minutes. While the rolls rest, preheat oven to 350ºF.\r\nRemove the plastic wrap and bake for about 30 minutes, rotating halfway thorough, until golden brown.\r\nWhile the rolls bake, combine the ingredients for the frosting, starting with just 3 Tbsp of the non-dairy milk. Stir, then add more milk as necessary 1 tsp at a time. If you accidentally add too much liquid, just stir in more powdered sugar.\r\nWhen the rolls are done baking, remove from the oven and let sit 5 minutes. Drizzle the rolls with the frosting and serve immediately. Enjoy!','<ul>\r\n<li>I’ve used both _soy milk_ and *almond milk* successfully with this recipe.</li>\r\n<li>Warm places: in a sunny window, on top of the fridge, on the dash of your car (no joke), in the microwave with a hot cup of water (but DON’T actually microwave the dough..), in your oven with the dough-proofing setting on, etc.</li>\r\n</ul>','Raquel Smith',NULL,NULL,NULL,'American','Breakfast','2016-12-21 15:16:13','189','2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','350683'),
	(22,33469,'Leek & Artichoke Quiche','','This Leek & Artichoke Quiche with Red Peppers is my [b]favorite brunch recipe[/b] ever. It\'s also amazing for dinner! With extra pie crust for all you crust-lovers out there!',NULL,'PT1H','PT35M','PT1H35M','8 slices','1 slice','711','46','1 leek\r\n2 tsp olive oil\r\n4 eggs\r\n1 cup milk\r\n1/4 cup artichoke hearts, cut into bite-sized pieces\r\n1/4 cup sliced roasted red pepper\r\n1/4 tsp salt\r\n1 cup cheddar cheese\r\n1 recipe <a href=\"http://mycaliforniaroots.com/vegan-pie-crust/\" target=\"_blank\">pie crust</a>','Prepare the pie crust. Let rest in the fridge for 30 minutes, then roll out into a 12\" circle and place in a greased 10\" tart pan. Let the extra crust hang over the edge and freeze for 20 minutes.\r\nPreheat your oven to 350ºF.\r\nSlice the leek into 1/4\" rounds. Heat a skillet over medium-high heat and add the olive oil and leeks. Cook, stirring often, until the leeks are soft and browned in some spots.\r\nScramble the eggs in a large bowl. Add the cooked leeks, milk, artichoke hearts, roasted red pepper, salt, and about 2/3 of the cheese. Mix to combine.\r\nPlace a sheet of parchment over the frozen pie crust, then fill with pie weights. Bake for 10 minutes, then remove the pie weights and remove the overhanging crust.\r\nPour in the egg filling. Top with the remaining cheese, then bake for about 35 minutes, until golden on top and mostly firm in the middle.\r\nLet cool for about 10 minutes before removing from the tart pan and serving. Eat!','<ul>\r\n<li>I used canned artichoke hearts and roasted red pepper.</li>\r\n<li>I used the back of a spoon to press the overhanging crust into the edge of the tart pan, causing it to separate. If you\'re using a pie dish, scissors might work better.</li>\r\n<li>If you are using my pie crust recipe but you aren\'t looking for a vegan crust, just replace the vegan butter with regular salted butter.</li>\r\n<li>If you are dairy-free, use the vegan pie crust as written and use plain, unsweetened soy milk in the quiche and omit the cheese.</li>\r\n</ul>','Raquel Smith',NULL,NULL,NULL,'American','Breakfast','2016-12-21 15:23:01','23','50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','350689'),
	(3,33472,'Homemade Dog Treats','','Calling all dog lovers for a cute holiday baking project involving HOMEMADE DOG TREATS and BACON PB GLAZE! lols, life is awesome.',NULL,'PT10M','PT20M','PT30M','30 biscuits','1 biscuit','64','0','!Dog biscuits:\r\n1 cup pumpkin\r\n½ cup peanut butter\r\n2 eggs\r\n¼ cup oil*\r\n2½ cups whole wheat flour\r\n1 teaspoon baking soda\r\n!Glaze:\r\n2 tablespoons bacon grease, melted\r\n¼ cup smooth peanut butter','Preheat oven to 350 degrees.\r\nCombine pumpkin, peanut butter, eggs, and oil in a bowl. Add in baking soda and whole wheat flour. Stir until a stiff dough forms. Knead dough or mix just until flour is incorporated.\r\nRoll out dough with a rolling pin and use a cookie cutter to cut out dog bone shapes, or just bake into little circles like cookies. Bake for 15 minutes.\r\nWhisk the bacon grease and peanut butter until very smooth. Drizzle over the treats and cool till glaze hardens (it does best in the fridge or freezer).','We just used a basic canola oil, but we also give Sage coconut oil for her fur/skin, and I think coconut oil would work nicely here. You can also use coconut oil in place of the bacon grease in the glaze, but, I mean, come on. It\'s bacon grease. SO YUMMY.\r\n\r\nAll ingredients are considered safe for dogs, but as with humans, it’s always a good idea to make sure there are no doggie allergies or sensitivities to any of the ingredients.','Lindsay Ostrom',NULL,NULL,NULL,'Dog Gourmet','Snack','2016-12-21 15:44:13','8','8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','350714'),
  (174, 2110, 'Italian Pear Filled Cookies', '', '', '', '', '', '', '20 cookies', '', '', '', '!For the dough:\n\r\n \n2 cups flour\n\r\n  \n1 egg\n\r\n \n1 egg yolk\n\r\n  \n1/2 cup sugar\n\r\n \n1/2 cup cold butter, cut into small cubes\n\r\n \n1/2 tsp baking powder\n\r\n \n1 tsp vanilla\n\r\n \npinch of salt\n\r\n \n!For the filling:\n\r\n \n2 pears, peeled and diced\n\r\n \n3 1/2 Tbsp sugar\n\r\n  \n1/2 cup water\n\r\n \njuice from 1/2 lemon\n\r\n\n', '\r\n\n!For the dough:\n\r\n\nPre- heat oven to 350°.\r\n  On a flat surface add together flour and salt. Make a well in the center and add the egg and yolk, baking powder, sugar, vanilla and butter. Work the ingredients together quickly to form a soft dough.\r\n  Wrap the dough in plastic and refrigerate for approximately 30 minutes.\r\n\n!For the filling:\n\r\n\nWhile the dough is in the fridge, add the diced pears, lemon juice and water to a small to medium sized pot.\r\n  Cook on low, stirring occasionally, until the pears become soft and the liquid has evaporated (make sure they don\'t turn burn). Remove from heat, add the sugar, and mix well.\r\n Remove the dough from the fridge, knead a couple of times and then roll out about half the dough into about a 1/8\" sheet.\r\n  Use a cookie cutter to cut into shapes. Place cut out flowers on a parchment-lined cookie sheet.\r\n  In the middle of each cookie place a teaspoon full of filling and top with second cookie.\r\n Use your fingers to pinch the sides of the cookies closed. Dipping finger tips in water helps to seal. Continue until all cut outs are complete, then repeat with the remaining dough.\r\n  Bake for approximately 13-15 minutes. Let cool completely and dust with plenty of powdered sugar.\r\n\n', '', 'An Italian in my kitchen', '<img class=\"aligncenter size-full wp-image-2108\" src=\"http://blog.raquelmsmith.webfactional.com/wp-content/uploads/2015/03/Italian-pear-filled-cookies-8-1-of-1.jpg\" alt=\"Italian pear filled cookies\" width=\"640\" height=\"949\" />\r\n\r\nHello everyone I am Rosemary and I blog at<a href=\"http://anitalianinmykitchen.com/\" target=\"_blank\"> An Italian in my kitchen.</a>  I have been living in Rome, Italy for the past 20+ years, what an experience that is, I must say.  I love sharing the recipes I have learned and created with help from my Italian family and friends.  Today I am here and guest posting for Raquel,  giving her a hand during this amazing time in her life.  I would also like to wish her and her husband love and happiness for many years to come.  Tanti Tanti Auguri!\r\n\r\nNow for the Italian Pear filled Cookies, these are made with a delicious, easy and simple cookie dough  filled with a slow-cooked pear filling.  I made them on Friday hoping  to serve them to my cousins who were visiting from Toronto, but they were gone by Saturday. When the Italian likes something he really likes something.\r\n\r\n<img class=\"aligncenter size-full wp-image-2111\" src=\"http://blog.raquelmsmith.webfactional.com/wp-content/uploads/2015/03/Italian-pear-filled-cookies-3-1-of-1.jpg\" alt=\"Italian pear filled cookies\" width=\"625\" height=\"450\" />\r\n\r\n<img class=\"aligncenter size-full wp-image-2112\" src=\"http://blog.raquelmsmith.webfactional.com/wp-content/uploads/2015/03/Italian-pear-filled-cookies-4-1-of-1.jpg\" alt=\"Italian pear filled cookies\" width=\"625\" height=\"450\" />\r\n\r\nI think with the cold winter that a lot of people have suffered through, these yummy flower-shaped Italian Pear Filled Cookies are the perfect start to Spring.  Enjoy!<img class=\"aligncenter size-full wp-image-2106\" src=\"http://blog.raquelmsmith.webfactional.com/wp-content/uploads/2015/03/Italian-pear-filled-cookies-5-1-of-1.jpg\" alt=\"Italian pear filled cookies\" width=\"640\" height=\"949\" /><!--more-->\r\n<div class=\"easyrecipe\"> \r\n<div class=\"item ERName\">Italian Pear Filled Cookies</div>\r\n<div class=\"ERClear\"></div>\r\n<div class=\"ERHead\"><span class=\"xlate\">Recipe Type</span>: <span class=\"type\">Baked Goods</span></div>\r\n<div class=\"ERHead\">Author: <span class=\"author\">An Italian in my kitchen</span></div>\r\n<div class=\"ERHead\">Serves: <span class=\"yield\">20 cookies</span></div>\r\n<div class=\"ERIngredients\">\r\n<div class=\"ERIngredientsHeader\">Ingredients</div>\r\n<ul class=\"ingredients\">\r\n  <li class=\"ERSeparator\">For the dough:</li>\r\n <li class=\"ingredient\">2 cups flour</li>\r\n  <li class=\"ingredient\">1 egg</li>\r\n <li class=\"ingredient\">1 egg yolk</li>\r\n  <li class=\"ingredient\">1/2 cup sugar</li>\r\n <li class=\"ingredient\">1/2 cup cold butter, cut into small cubes</li>\r\n <li class=\"ingredient\">1/2 tsp baking powder</li>\r\n <li class=\"ingredient\">1 tsp vanilla</li>\r\n <li class=\"ingredient\">pinch of salt</li>\r\n <li class=\"ERSeparator\">For the filling:</li>\r\n <li class=\"ingredient\">2 pears, peeled and diced</li>\r\n <li class=\"ingredient\">3 1/2 Tbsp sugar</li>\r\n  <li class=\"ingredient\">1/2 cup water</li>\r\n <li class=\"ingredient\">juice from 1/2 lemon</li>\r\n</ul>\r\n</div>\r\n<div class=\"ERInstructions\">\r\n<div class=\"ERInstructionsHeader\">Instructions</div>\r\n<div class=\"instructions\">\r\n<div class=\"ERSeparator\">For the dough:</div>\r\n<ol>\r\n  <li class=\"instruction\">Pre- heat oven to 350°.</li>\r\n  <li class=\"instruction\">On a flat surface add together flour and salt. Make a well in the center and add the egg and yolk, baking powder, sugar, vanilla and butter. Work the ingredients together quickly to form a soft dough.</li>\r\n <li class=\"instruction\">Wrap the dough in plastic and refrigerate for approximately 30 minutes.</li>\r\n</ol>\r\n<div class=\"ERSeparator\">For the filling:</div>\r\n<ol>\r\n  <li class=\"instruction\">While the dough is in the fridge, add the diced pears, lemon juice and water to a small to medium sized pot.</li>\r\n <li class=\"instruction\">Cook on low, stirring occasionally, until the pears become soft and the liquid has evaporated (make sure they don\'t turn burn). Remove from heat, add the sugar, and mix well.</li>\r\n  <li class=\"instruction\">Remove the dough from the fridge, knead a couple of times and then roll out about half the dough into about a 1/8\" sheet.</li>\r\n <li class=\"instruction\">Use a cookie cutter to cut into shapes. Place cut out flowers on a parchment-lined cookie sheet.</li>\r\n <li class=\"instruction\">In the middle of each cookie place a teaspoon full of filling and top with second cookie.</li>\r\n  <li class=\"instruction\">Use your fingers to pinch the sides of the cookies closed. Dipping finger tips in water helps to seal. Continue until all cut outs are complete, then repeat with the remaining dough.</li>\r\n <li class=\"instruction\">Bake for approximately 13-15 minutes. Let cool completely and dust with plenty of powdered sugar.</li>\r\n</ol>\r\n</div>\r\n</div>\r\n<div class=\"ERNutrition\"></div>\r\n<div class=\"endeasyrecipe\">3.2.2929</div>\r\n</div>\r\n&nbsp;\r\n\r\n&nbsp;', '<div class=\"easyrecipe\"> \r\n<div class=\"item ERName\">Italian Pear Filled Cookies</div>\r\n<div class=\"ERClear\"></div>\r\n<div class=\"ERHead\"><span class=\"xlate\">Recipe Type</span>: <span class=\"type\">Baked Goods</span></div>\r\n<div class=\"ERHead\">Author: <span class=\"author\">An Italian in my kitchen</span></div>\r\n<div class=\"ERHead\">Serves: <span class=\"yield\">20 cookies</span></div>\r\n<div class=\"ERIngredients\">\r\n<div class=\"ERIngredientsHeader\">Ingredients</div>\r\n<ul class=\"ingredients\">\r\n  <li class=\"ERSeparator\">For the dough:</li>\r\n <li class=\"ingredient\">2 cups flour</li>\r\n  <li class=\"ingredient\">1 egg</li>\r\n <li class=\"ingredient\">1 egg yolk</li>\r\n  <li class=\"ingredient\">1/2 cup sugar</li>\r\n <li class=\"ingredient\">1/2 cup cold butter, cut into small cubes</li>\r\n <li class=\"ingredient\">1/2 tsp baking powder</li>\r\n <li class=\"ingredient\">1 tsp vanilla</li>\r\n <li class=\"ingredient\">pinch of salt</li>\r\n <li class=\"ERSeparator\">For the filling:</li>\r\n <li class=\"ingredient\">2 pears, peeled and diced</li>\r\n <li class=\"ingredient\">3 1/2 Tbsp sugar</li>\r\n  <li class=\"ingredient\">1/2 cup water</li>\r\n <li class=\"ingredient\">juice from 1/2 lemon</li>\r\n</ul>\r\n</div>\r\n<div class=\"ERInstructions\">\r\n<div class=\"ERInstructionsHeader\">Instructions</div>\r\n<div class=\"instructions\">\r\n<div class=\"ERSeparator\">For the dough:</div>\r\n<ol>\r\n  <li class=\"instruction\">Pre- heat oven to 350°.</li>\r\n  <li class=\"instruction\">On a flat surface add together flour and salt. Make a well in the center and add the egg and yolk, baking powder, sugar, vanilla and butter. Work the ingredients together quickly to form a soft dough.</li>\r\n <li class=\"instruction\">Wrap the dough in plastic and refrigerate for approximately 30 minutes.</li>\r\n</ol>\r\n<div class=\"ERSeparator\">For the filling:</div>\r\n<ol>\r\n  <li class=\"instruction\">While the dough is in the fridge, add the diced pears, lemon juice and water to a small to medium sized pot.</li>\r\n <li class=\"instruction\">Cook on low, stirring occasionally, until the pears become soft and the liquid has evaporated (make sure they don\'t turn burn). Remove from heat, add the sugar, and mix well.</li>\r\n  <li class=\"instruction\">Remove the dough from the fridge, knead a couple of times and then roll out about half the dough into about a 1/8\" sheet.</li>\r\n <li class=\"instruction\">Use a cookie cutter to cut into shapes. Place cut out flowers on a parchment-lined cookie sheet.</li>\r\n <li class=\"instruction\">In the middle of each cookie place a teaspoon full of filling and top with second cookie.</li>\r\n  <li class=\"instruction\">Use your fingers to pinch the sides of the cookies closed. Dipping finger tips in water helps to seal. Continue until all cut outs are complete, then repeat with the remaining dough.</li>\r\n <li class=\"instruction\">Bake for approximately 13-15 minutes. Let cool completely and dust with plenty of powdered sugar.</li>\r\n</ol>\r\n</div>\r\n</div>\r\n<div class=\"ERNutrition\"></div>\r\n<div class=\"endeasyrecipe\">3.2.2929</div>\r\n</div>', 'easyrecipe', '', 'Baked Goods', '2017-02-13 13:35:05', NULL, '', NULL, NULL, '', '', '', '', '', '', '');
